2	import { join } from "path";
3	
4	interface BaseConfigOptions {
5	    /**
6	     * The directory of the calling app (i.e. `__dirname` from the app's playwright.config.ts).
7	     */
8	    appDir: string;
9	
10	    /**
11	     * Optional local test directory for app-specific tests (relative to appDir).
12	     * If provided, a second project is added for app-specific tests.
13	     */
14	    localTestDir?: string;
15	
16	    /**
17	     * The name for the app-specific test project (e.g. "server", "standalone").
18	     */
19	    projectName: string;
20	
21	    /**
22	     * Optional webServer configuration to start the app before tests.
23	     */
24	    webServer?: PlaywrightTestConfig["webServer"];
25	
26	    /**
27	     * Number of parallel workers. Defaults to Playwright's default (half of CPU cores).
28	     */
29	    workers?: number;
30	}
31	
32	/**
33	 * Creates a base Playwright configuration that includes the shared trilium-e2e
34	 * tests and optionally app-specific tests.
35	 */
36	export function createBaseConfig({ appDir, localTestDir, projectName, webServer, workers }: BaseConfigOptions) {
37	    const port = process.env["TRILIUM_PORT"] ?? "8082";
38	    const baseURL = process.env["BASE_URL"] || `http://127.0.0.1:${port}`;
39	    const sharedTestDir = join(__dirname);
40	
41	    const projects: PlaywrightTestConfig["projects"] = [
42	        {
43	            name: `${projectName}-shared`,
44	            testDir: sharedTestDir,
45	            use: { ...devices["Desktop Chrome"] },
46	        }
47	    ];
48	
49	    if (localTestDir) {
50	        projects.push({
51	            name: projectName,
52	            testDir: join(appDir, localTestDir),
53	            use: { ...devices["Desktop Chrome"] },
54	        });
55	    }
56	
57	    return defineConfig({
58	        reporter: [["list"], ["html", { outputFolder: join(appDir, "test-output") }]],
59	        outputDir: join(appDir, "test-output"),
60	        retries: 3,
61	        use: {
62	            baseURL,
63	            trace: "on-first-retry",
