161	type SyncStep = "connecting" | "syncing" | "finalizing";
162	
163	function getSyncStep(stats: { outstandingPullCount: number; totalPullCount: number | null; initialized: boolean }): SyncStep {
164	    if (stats.initialized) {
165	        return "finalizing"; // will reload momentarily
166	    }
167	    if (stats.totalPullCount !== null && stats.outstandingPullCount > 0) {
168	        return "syncing";
169	    }
170	    if (stats.totalPullCount !== null && stats.outstandingPullCount === 0) {
171	        return "finalizing";
172	    }
173	    return "connecting";
174	}
