176	function useWakeLock() {
177	    const wakeLockRef = useRef<WakeLockSentinel | null>(null);
178	
179	    useEffect(() => {
180	        if (!("wakeLock" in navigator)) return;
181	
182	        let released = false;
183	
184	        const acquireLock = () => {
185	            navigator.wakeLock.request("screen").then((lock) => {
186	                if (released) {
187	                    lock.release();
188	                } else {
189	                    wakeLockRef.current = lock;
190	                }
191	            }).catch(() => {
192	                // Wake Lock not supported or permission denied — ignore silently.
193	            });
194	        };
195	
196	        const onVisibilityChange = () => {
197	            if (document.visibilityState === "visible" && !released) {
198	                acquireLock();
199	            }
200	        };
201	
202	        acquireLock();
203	        document.addEventListener("visibilitychange", onVisibilityChange);
204	
205	        return () => {
206	            released = true;
207	            document.removeEventListener("visibilitychange", onVisibilityChange);
208	            wakeLockRef.current?.release();
209	            wakeLockRef.current = null;
210	        };
211	    }, []);
212	}
