224	
225	    const steps: { key: SyncStep; label: string }[] = [
226	        { key: "connecting", label: t("setup.sync-step-connecting") },
227	        { key: "syncing", label: t("setup.sync-step-syncing") },
228	        { key: "finalizing", label: t("setup.sync-step-finalizing") }
229	    ];
230	
231	    const currentIndex = steps.findIndex((s) => s.key === step);
232	
233	    const syncingDone = currentIndex > steps.findIndex((s) => s.key === "syncing");
234	    let progress = 0;
235	    if (syncingDone) {
236	        progress = 100;
237	    } else if (stats.totalPullCount) {
238	        progress = Math.round(((stats.totalPullCount - stats.outstandingPullCount) / stats.totalPullCount) * 100);
239	    }
240	
241	    return (
242	        <SetupPage
243	            className="sync-in-progress"
244	            illustration={<SyncIllustration targetDevice={device} />}
245	            title={t("setup.sync-in-progress-title")}
246	        >
247	            <Card className="sync-steps">
248	                {steps.map((s, i) => (
249	                    <CardSection className={i < currentIndex ? "completed" : i === currentIndex ? "active" : ""} key={s.key}>
250	                        <Icon icon={i < currentIndex ? "bx bx-check-circle" : i === currentIndex ? "bx bx-loader-circle bx-spin" : "bx bx-circle"} />{" "}
251	                        {s.label}
252	                        {s.key === "syncing" && (
253	                            <div class="sync-progress">
254	                                <progress value={syncingDone ? 1 : stats.totalPullCount! - stats.outstandingPullCount} max={syncingDone ? 1 : stats.totalPullCount!} />
255	                                <span>{progress}%</span>
256	                            </div>
257	                        )}
258	                    </CardSection>
259	                ))}
260	            </Card>
261	
262	            {isMobileApp() && (
263	                <Admonition type="note" className="sync-banner">
