278	        setOutstandingPullCount(resp.outstandingPullCount);
279	        setTotalPullCount(resp.totalPullCount);
280	        setInitialized(resp.initialized);
281	    }
282	
283	    useEffect(() => {
284	        const interval = setInterval(refresh, 1000);
285	        refresh();
286	
287	        return () => clearInterval(interval);
288	    }, []);
289	    return { outstandingPullCount, totalPullCount, initialized };
