330	    const isValid = syncServerHost.trim() !== "" && password !== "";
331	
332	    function raiseError(message: string) {
333	        setError(message);
334	        setErrorId(id => id + 1);
335	    }
336	
337	    async function handleFinishSetup() {
338	        try {
339	            const resp = await server.post<SetupSyncFromServerResponse>("setup/sync-from-server", {
340	                syncServerHost: syncServerHost.trim().replace(/\/+$/, ""),
341	                syncProxy: syncProxy.trim(),
