350	                raiseError(t("setup.sync-failed", { message: resp.error }));
351	            }
352	        } catch (e) {
353	            raiseError(e instanceof Error ? e.message : String(e));
354	        }
355	    }
356	
357	    return (
358	        <SetupPage
359	            className="sync-from-server top-aligned"
360	            title={t("setup.sync-from-server")}
361	            description={t("setup.sync-from-server-page-description")}
362	            illustration={<SyncIllustration targetDevice="server" />}
363	            error={error}
