580	async function getNetworkAddresses(): Promise<NetworkAddressesResponse> {
581	    if (!isElectron()) {
582	        // The browser already reached this server over the network, so the
583	        // address it's using is reachable by definition.
584	        return { addresses: [`${location.protocol}//${location.host}`], reachableOnNetwork: true };
585	    }
586	
587	    // Node's `os` module isn't available in the renderer (node integration is
588	    // disabled), and the desktop renderer's `location` points at the internal
589	    // `trilium-app://` protocol rather than the real HTTP listener. So the
590	    // server enumerates its interfaces and builds the reachable URLs (correct
591	    // protocol and port included), and reports whether it's actually bound to a
592	    // network-reachable interface.
593	    return await server.get<NetworkAddressesResponse>("network-addresses");
594	}
