596	async function allowLanAccessAndRestart() {
597	    // Shows a native confirmation dialog (LAN exposure is a security tradeoff)
598	    // and persists the choice to security.json. Only restart once the user has
599	    // actually confirmed — otherwise the binding wouldn't change anyway.
600	    const confirmed = await window.electronApi?.security.setLanAccessEnabled(true);
601	    if (confirmed) {
602	        window.electronApi?.window.restartApp();
603	    }
604	}
