19	/** The settings page shown when no specific section was requested and none was viewed yet this session. */
20	const DEFAULT_SECTION = "_optionsAppearance";
21	
22	/**
23	 * The settings dialog, opened via the `showOptions` command. Settings open in a dialog rather than
24	 * a hoisted tab (which confused users by seemingly hiding the note tree): the full-height sidebar
25	 * lists the settings pages while the body renders the active one through a dedicated note context.
26	 *
27	 * On mobile the sidebar and the page become a master-detail flow instead: the dialog first shows
28	 * only the list of pages, tapping one reveals it full-screen with a back button in the header.
29	 */
30	export default function OptionsDialog() {
31	    const [ shown, setShown ] = useState(false);
32	    const parentComponent = useContext(ParentComponent);
33	    const [ noteContext, setNoteContext ] = useState(() => new NoteContext("_options-dialog"));
34	    // Remembers the page last viewed this session so reopening the dialog lands there instead of
35	    // always on Appearance. Kept in component state (resets on reload), not persisted.
36	    const [ lastSection, setLastSection ] = useState<string | null>(null);
37	    const modalRef = useRef<HTMLDivElement>(null);
38	    const isMobile = utils.isMobile();
39	    const { isMasterDetail, mobileView, switchMobileView, resetMobileView } = useMobileMasterDetail(modalRef, "options-slide");
40	
41	    useTriliumEvent("showOptions", async ({ section }) => {
42	        const noteContext = new NoteContext("_options-dialog");
43	        await noteContext.setNote(section ?? lastSection ?? DEFAULT_SECTION, { keepActiveDialog: true });
44	
45	        // Events triggered at note context level (e.g. the save indicator) would not work since the note context has no parent component. Propagate events to parent component so that they can be handled properly.
46	        noteContext.triggerEvent = (name, data) => parentComponent?.handleEventInChildren(name, data);
47	        setNoteContext(noteContext);
48	        // Requesting a specific section (e.g. "set up a password") skips the mobile master list.
49	        resetMobileView(section ? "page" : "list");
50	        setShown(true);
51	    });
52	
53	    // Keep navigation between settings pages (sidebar entries, "Related settings" links) inside the
54	    // dialog; links to regular notes open in the quick-edit popup instead.
55	    useContainedLinkNavigation(modalRef, useCallback((notePath, viewScope) => {
56	        if (notePath.split("/").at(-1)?.startsWith("_options")) {
57	            void noteContext.setNote(notePath, { viewScope, keepActiveDialog: true });
58	            switchMobileView("page");
59	        } else {
60	            void appContext.triggerCommand("openInPopup", { noteIdOrPath: notePath });
61	        }
62	    }, [ noteContext, switchMobileView ]));
63	
64	    return (
65	        <NoteContextContext.Provider value={noteContext}>
66	            <Modal
67	                modalRef={modalRef}
68	                title={t("options.title")}
69	                header={isMasterDetail && (mobileView === "page" ? <MobilePageHeader onBack={() => switchMobileView("list")} /> : <MobilePageHeader />)}
70	                sidebar={isMasterDetail ? undefined : <SettingsSidebar />}
71	                isFullPageOnMobile
72	                customTitleBarButtons={!isMobile ? [{
73	                    iconClassName: "bx-expand-alt",
74	                    title: t("popup-editor.maximize"),
75	                    onClick: async () => {
76	                        if (!noteContext.noteId) return;
77	                        const { noteId, hoistedNoteId } = noteContext;
78	                        await appContext.tabManager.openInNewTab(noteId, hoistedNoteId, true);
79	                        setShown(false);
80	                    }
81	                }] : undefined}
82	                className="options-dialog"
83	                size="lg"
84	                show={shown}
85	                onHidden={() => {
86	                    // Remember the settings page in view so the next open lands on it.
87	                    if (noteContext.noteId) {
88	                        setLastSection(noteContext.noteId);
89	                    }
90	                    setShown(false);
91	                }}
92	            >
93	                {isMasterDetail && (
94	                    <div className="options-mobile-nav">
95	                        <MobileSettingsList onSelect={(noteId) => {
96	                            void noteContext.setNote(noteId, { keepActiveDialog: true });
97	                            switchMobileView("page");
98	                        }} />
99	                    </div>
100	                )}

